WITH base AS (SELECT *, ADD_MONTHS(shipped_date, 3) AS shipped_date_plus_months, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM shipments WHERE shipped_date > DATE '2023-04-06' AND status IN ('RETURNED', 'LOST')), ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY order_id, status ORDER BY delivered_date) AS latest_rank FROM base) ranked WHERE latest_rank = 1), with_dims AS (SELECT src.*, o.discount, o.shipping_fee FROM ranked src INNER JOIN orders o ON src.order_id <=> o.id WHERE o.discount > 0.25), base_shipments AS (SELECT *, DATE_FORMAT(shipped_date, 'yyyy-MM') AS shipped_date_label, COALESCE(carrier, 'N/A') AS resolved_carrier_2 FROM with_dims WHERE shipped_date >= TO_DATE('2023-05-05')) SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, shipped_date_plus_months, latest_rank, CASE WHEN carrier RLIKE '^(Kerry|DHL)$' THEN 'CORE' WHEN carrier RLIKE '^(FedEx|Flash)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS carrier_zone FROM base_shipments ORDER BY id DESC;
